#!/usr/bin/env node

import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const catalog = JSON.parse(await readFile(resolve("src/docs-registry.json"), "utf8"));
const lines = [
  "# Poyraz UI Registry Catalog",
  "",
  "> Generated by `pnpm docs:sync` from registry metadata. Do not edit counts, paths, or dependencies manually.",
  "",
  `Components: ${catalog.counts.components} | Blocks: ${catalog.counts.blocks}`,
  "",
  "## Install",
  "",
  "```bash",
  "pnpm dlx shadcn@latest add @poyraz/button",
  "```",
  "",
];

for (const group of [...catalog.navigation, { section: "Blocks", items: catalog.blocks }]) {
  lines.push(`## ${group.section}`, "", "| Item | Type | Runtime dependencies | Docs |", "| --- | --- | --- | --- |");
  for (const item of group.items) {
    const docs = item.href;
    lines.push(`| \`${item.name}\` | \`${item.type}\` | ${item.dependencies.join(", ") || "None"} | [Open](https://ui.poyrazavsever.com${docs}) |`);
  }
  lines.push("");
}

lines.push(
  "## Source of truth",
  "",
  "Registry metadata lives under `registry/poyraz/**/registry.json`. Public install documents are generated under `public/r/`.",
  "",
);

await writeFile(resolve("COMPONENTS.md"), `${lines.join("\n").trimEnd()}\n`);
console.log("COMPONENTS.md synchronized with docs registry metadata.");
